python3 -c "
import csv
with open('/tmp/weooct2024all.xls', 'r', encoding='utf-16-le') as f:
    reader = csv.reader(f, delimiter='\t')
    header = next(reader)
    # Find year column indices
    year_cols = {}
    for i, h in enumerate(header):
        h = h.strip().strip('\ufeff')
        if h.isdigit() and 2020 <= int(h) <= 2030:
            year_cols[h] = i
    print('Year columns found:', sorted(year_cols.keys()))

    for row in reader:
        if len(row) > 3:
            iso = row[1].strip()
            if iso == '915':
                subject = row[2].strip()
                if subject in ['NGDP_RPCH', 'NGDPD', 'NGDP_D', 'NGDP', 'NGDP_R']:
                    desc = row[4].strip() if len(row) > 4 else ''
                    units = row[6].strip() if len(row) > 6 else ''
                    print(f'{subject} - {desc} ({units}):')
                    for year in sorted(year_cols.keys()):
                        idx = year_cols[year]
                        val = row[idx].strip() if idx < len(row) else 'N/A'
                        print(f'  {year}: {val}')
" 2>&1
